 1	use anyhow::Result;
 2	use defc_proc_macro::http;
 3	
 4	#[http(impl = UserCenterImpl)]
 5	pub trait UserCenter {
 6	    #[options(ident = "options")]
 7	    type Options: OptionsProvider;
 8	
 9	    #[post("https://{options.host()}/v1/users")]
10	    #[headers(Authorization = "Bearer {options.token()}")]
11	    #[headers(Content-Type = "application/json", Accept = "application/json")]
12	    #[body(user)]
13	    fn create_user(&self, user: CreateUserRequest) -> Result<User>;
14	
15	    #[get("https://{options.host()}/v1/users/{id}")]
16	    #[headers(Authorization = "Bearer {options.token()}")]
17	    fn get_user(&self, id: u64) -> Result<User>;
18	}
19	
20	pub trait OptionsProvider {
21	    fn host(&self) -> &str;
22	    fn token(&self) -> &str;
23	}
24	
25	#[derive(Debug, serde::Deserialize)]
26	pub struct User {
27	    pub id: u64,
28	    pub name: String,
29	}
30	
31	#[derive(serde::Serialize)]
32	pub struct CreateUserRequest<'a> {
33	    pub name: &'a str,
34	}
35	
36	pub struct UserCenterOptions<'a> {
37	    pub host: &'a str,
38	    pub token: &'a str,
39	}
40	
41	impl OptionsProvider for UserCenterOptions<'_> {
42	    fn host(&self) -> &str {
43	        self.host
44	    }
45	
46	    fn token(&self) -> &str {
47	        self.token
48	    }
49	}

