 17	const (
 18		apiMethodOptions         = "OPTIONS"
 19		apiMethodResponseHandler = "RESPONSEHANDLER"
 20	
 21		// Deprecated: use apiMethodOptions instead
 22		apiMethodInner = "INNER"
 23		// Deprecated: use apiMethodResponseHandler instead
 24		apiMethodResponse = "RESPONSE"
 25	
 26		FeatureApiCache        = "api/cache"
 27		FeatureApiLog          = "api/log"
 28		FeatureApiLogx         = "api/logx"
 29		FeatureApiClient       = "api/client"
 30		FeatureApiPage         = "api/page"
 31		FeatureApiError        = "api/error"
 32		FeatureApiNoRt         = "api/nort"
 33		FeatureApiFuture       = "api/future"
 34		FeatureApiIgnoreStatus = "api/ignore-status"
 35		FeatureApiGzip         = "api/gzip"
 36		FeatureApiRetry        = "api/retry"
 37		FeatureApiGetBody      = "api/get-body"
 38	)
