 40	func (builder *CliBuilder) buildApi(w io.Writer) error {
 41		inspectCtx, err := builder.inspectApi()
 42		if err != nil {
 43			return fmt.Errorf("inspectApi(%s, %d): %w", quote(join(builder.pwd, builder.file)), builder.pos, err)
 44		}
 45		return inspectCtx.Build(w)
 46	}
 47	
 48	type apiContext struct {
 49		Package   string
 50		BuildTags []string
 51		Ident     string
 52		Generics  map[string]ast.Expr
 53		Methods   []*Method
 54		Features  []string
 55		Imports   []string
 56		Funcs     []string
 57		Doc       Doc
 58	}
 59	
 60	func (ctx *apiContext) Build(w io.Writer) error {
 61		if !checkResponse(ctx.Methods) {
 62			return fmt.Errorf("checkResponse: no '%s() T' method found in Interface", apiMethodResponse)
 63		}
 64	
 65		var declHasInner bool
 66		for _, method := range ctx.Methods {
 67			if isInner(method.Ident) {
 68				declHasInner = true
 69			}
 70	
 71			if !isResponse(method.Ident) && !isInner(method.Ident) {
 72				if l := len(method.Out); l == 0 || !checkErrorType(method.Out[l-1]) {
 73					return fmt.Errorf("checkErrorType: no 'error' found in method %s returned values",
 74						quote(method.Ident))
 75				}
 76			}
 77	
 78			if (isResponse(method.Ident) || isInner(method.Ident)) &&
 79				(len(method.In) != 0 || len(method.Out) != 1) {
 80				return fmt.Errorf(
 81					"%s method can only have no income params "+
 82						"and 1 returned value", quote(method.Ident))
 83			}
 84	
 85			if isResponse(method.Ident) {
 86				methodOut0 := method.Out[0]
 87				if !checkResponseType(methodOut0) {
 88					return fmt.Errorf(
 89						"checkResponseType: returned type of %s "+
 90							"should be kind of "+
 91							"*ast.Ident/"+
 92							"*ast.StarExpr/"+
 93							"*ast.SelectorExpr/"+
 94							"*ast.IndexExpr/"+
 95							"*ast.IndexListExpr"+
 96							", got %T",
 97						quote(apiMethodResponse),
 98						methodOut0)
 99				}
100			}
101	
102			// [2023-06-11] we limit 2 returned values on v1.0.0, now it is time to cancel this limitation
103			/*
104				if len(method.Out) > 2 {
105					return fmt.Errorf("%s method expects 2 returned value at most, got %d",
106						quote(method.Ident),
107						len(method.Out))
108				}
109			*/
110		}
111	
112		if !declHasInner &&
113			(in(ctx.Features, FeatureApiCache) ||
114				in(ctx.Features, FeatureApiLog) || in(ctx.Features, FeatureApiLogx) ||
115				in(ctx.Features, FeatureApiClient)) {
116			return fmt.Errorf("api/cache, api/log, api/logx and api/client features require an `Options` method")
117		}
118	
119		// When using the api/future feature without enabling the api/error feature, it may cause connections
120		// to not be closed properly, potentially leading to memory leak risks. To prevent this from happening,
121		// when the api/future feature is enabled, the api/error feature must also be enforced.
122		if in(ctx.Features, FeatureApiFuture) && !in(ctx.Features, FeatureApiError) {
123			ctx.Features = append(ctx.Features, FeatureApiError)
124		}
125	
126		// We do not allow the use of api/ignore-status without enabling the api/future feature, as this would
127		// cause callers to miss out on determining exceptional response codes.
128		if in(ctx.Features, FeatureApiIgnoreStatus) && !in(ctx.Features, FeatureApiFuture) {
129			return fmt.Errorf("api/ignore-status feature requires api/future feature to be enabled")
130		}
131	
132		if in(ctx.Features, FeatureApiGzip) && in(ctx.Features, FeatureApiNoRt) {
133			return fmt.Errorf("api/gzip feature requires api/nort feature to be disabled")
134		}
135	
136		if err := ctx.genApiCode(w); err != nil {
137			return fmt.Errorf("genApiCode: %w", err)
138		}
139	
140		return nil
141	}
