143	func (ctx *apiContext) SortGenerics() []string {
144		idents := make([]string, 0, len(ctx.Generics))
145		for k := range ctx.Generics {
146			idents = append(idents, k)
147		}
148		sort.Slice(idents, func(i, j int) bool {
149			return ctx.Generics[idents[i]].Pos() < ctx.Generics[idents[j]].Pos()
150		})
151		return idents
152	}
153	
154	func (ctx *apiContext) GenericsRepr(withType bool) string {
155		if len(ctx.Generics) == 0 {
156			return ""
157		}
158	
159		var dst bytes.Buffer
160		dst.WriteByte('[')
161		for index, name := range ctx.SortGenerics() {
162			expr := ctx.Generics[name]
163			dst.WriteString(name)
164			if withType {
165				dst.WriteByte(' ')
166				dst.WriteString(ctx.Doc.Repr(expr))
167			}
168			if index < len(ctx.Generics)-1 {
169				dst.WriteString(", ")
170			}
171		}
172		dst.WriteByte(']')
173	
174		return dst.String()
175	}
176	
177	func (ctx *apiContext) HasFeature(feature string) bool {
178		for _, current := range ctx.Features {
179			if current == feature {
180				return true
181			}
182		}
183		return false
184	}
185	
186	func (ctx *apiContext) HasHeader() bool {
187		for _, method := range ctx.Methods {
188			if method.Header != "" {
189				return true
190			}
191		}
192		return false
193	}
194	
195	func (ctx *apiContext) HasBody() bool {
196		for _, method := range ctx.Methods {
197			if httpMethodHasBody(method.MethodHTTP()) && headerHasBody(method.TmplHeader()) {
198				return true
199			}
200		}
201		return false
202	}
203	
204	func (ctx *apiContext) HasInner() bool {
205		return hasInner(ctx.Methods)
206	}
207	
208	func (ctx *apiContext) InnerType() ast.Node {
209		for _, method := range ctx.Methods {
210			if isInner(method.Ident) {
211				return method.Out[0]
212			}
213		}
214		return nil
215	}
216	
217	func (ctx *apiContext) MethodResponse() string {
218		for _, method := range ctx.Methods {
219			if isResponse(method.Ident) {
220				return method.Ident
221			}
222		}
223		return apiMethodResponse
224	}
225	
226	func (ctx *apiContext) MethodInner() string {
227		for _, method := range ctx.Methods {
228			if isInner(method.Ident) {
229				return method.Ident
230			}
231		}
232		return apiMethodInner
233	}
