235	func (ctx *apiContext) MergedImports() (imports []string) {
236		imports = []string{
237			quote("fmt"),
238			quote("io"),
239			quote("net/http"),
240			quote("text/template"),
241		}
242	
243		if ctx.HasFeature(FeatureApiLog) || ctx.HasFeature(FeatureApiLogx) {
244			imports = append(imports, quote("time"))
245			imports = append(imports, quote("context"))
246		}
247	
248		if ctx.HasFeature(FeatureApiNoRt) {
249			imports = append(imports,
250				quote("bytes"),
251				quote("sync"),
252				quote("reflect"))
253		} else {
254			imports = append(imports, parseImport("__rt github.com/x5iu/defc/runtime"))
255		}
256	
257		if ctx.HasHeader() {
258			imports = append(imports, quote("bufio"))
259			imports = append(imports, quote("net/textproto"))
260			if ctx.HasBody() && ctx.HasFeature(FeatureApiLogx) {
261				imports = append(imports, quote("bytes"))
262			}
263		}
264	
265		if importContext(ctx.Methods) {
266			imports = append(imports, quote("context"))
267		}
268	
269		for _, imp := range ctx.Imports {
270			if !in(imports, imp) {
271				imports = append(imports, parseImport(imp))
272			}
273		}
274	
275		return imports
276	}
277	
278	func (ctx *apiContext) AdditionalFuncs() (funcMap map[string]string) {
279		funcMap = make(map[string]string, len(ctx.Funcs))
280		for _, fn := range ctx.Funcs {
281			if key, value, ok := cutkv(fn); ok {
282				funcMap[key] = value
283			}
284		}
285		return funcMap
286	}
