288	func (builder *CliBuilder) inspectApi() (*apiContext, error) {
289		fset := token.NewFileSet()
290	
291		f, err := parser.ParseFile(fset, builder.file, builder.doc.Bytes(), parser.ParseComments)
292		if err != nil {
293			return nil, err
294		}
295	
296		var (
297			genDecl   *ast.GenDecl
298			typeSpec  *ast.TypeSpec
299			ifaceType *ast.InterfaceType
300		)
301	
302		line := builder.pos + 1
303	inspectDecl:
304		for _, declIface := range f.Decls {
305			if surroundLine(fset, declIface, line) {
306				if decl, ok := declIface.(*ast.GenDecl); ok && decl.Tok == token.TYPE {
307					genDecl = decl
308					break inspectDecl
309				}
310			}
311		}
312	
313		if genDecl == nil {
314			return nil, fmt.Errorf(
315				"no available 'Interface' type declaration (*ast.GenDecl) found, "+
316					"available *ast.GenDecl are: \n\n"+
317					"%s\n\n", concat(nodeMap(f.Decls, fmtNode), "\n"))
318		}
319	
320	inspectType:
321		for _, specIface := range genDecl.Specs {
322			if afterLine(fset, specIface, line) {
323				if spec, ok := specIface.(*ast.TypeSpec); ok {
324					if iface, ok := spec.Type.(*ast.InterfaceType); ok && afterLine(fset, iface, line) {
325						typeSpec = spec
326						ifaceType = iface
327						break inspectType
328					}
329				}
330			}
331		}
332	
333		if ifaceType == nil {
334			return nil, fmt.Errorf(
335				"no available 'Interface' type declaration (*ast.InterfaceType) found, "+
336					"available *ast.GenDecl are: \n\n"+
337					"%s\n\n", concat(nodeMap(f.Decls, fmtNode), "\n"))
338		}
339	
340		for _, method := range ifaceType.Methods.List {
341			if funcType, ok := method.Type.(*ast.FuncType); ok {
342				if !checkInput(funcType) {
343					return nil, fmt.Errorf(""+
344						"input params for method %s should "+
345						"contain 'Name' and 'Type' both",
346						quote(method.Names[0].Name))
347				}
348			}
349		}
350	
351		apiFeatures := make([]string, 0, len(builder.feats))
352		for _, feature := range builder.feats {
353			if hasPrefix(feature, "api") {
354				apiFeatures = append(apiFeatures, feature)
355			}
356		}
357	
358		generics := make(map[string]ast.Expr, 16)
359		if typeSpec.TypeParams != nil {
360			for _, param := range typeSpec.TypeParams.List {
361				for _, name := range param.Names {
362					generics[name.Name] = param.Type
363				}
364			}
365		}
366	
367		return &apiContext{
368			Package:   builder.pkg,
369			BuildTags: parseBuildTags(builder.doc),
370			Ident:     typeSpec.Name.Name,
371			Generics:  generics,
372			Methods:   typeMap(ifaceType.Methods.List, builder.doc.InspectMethod),
373			Features:  apiFeatures,
374			Imports:   builder.imports,
375			Funcs:     builder.funcs,
376			Doc:       builder.doc,
377		}, nil
378	}
