380	func checkResponse(methods []*Method) bool {
381		for _, method := range methods {
382			if isResponse(method.Ident) {
383				return true
384			}
385		}
386		return false
387	}
388	
389	func checkResponseType(node ast.Node) bool {
390		switch node.(type) {
391		case *ast.Ident, *ast.StarExpr, *ast.SelectorExpr, *ast.IndexExpr, *ast.IndexListExpr:
392			return true
393		default:
394			return false
395		}
396	}
397	
398	func hasInner(methods []*Method) bool {
399		for _, method := range methods {
400			if isInner(method.Ident) {
401				return true
402			}
403		}
404		return false
405	}
406	
407	func importContext(methods []*Method) bool {
408		for _, method := range methods {
409			if method.HasContext() {
410				return true
411			}
412		}
413		return false
414	}
415	
416	func isResponse(ident string) bool {
417		ident = toUpper(ident)
418		return ident == apiMethodResponse || ident == apiMethodResponseHandler
419	}
420	
421	func isInner(ident string) bool {
422		ident = toUpper(ident)
423		return ident == apiMethodInner || ident == apiMethodOptions
424	}
425	
426	func httpMethodHasBody(method string) bool {
427		switch method {
428		case http.MethodGet:
429			return false
430		case http.MethodPost, http.MethodPut, http.MethodPatch:
431			return true
432		default:
433			return false
434		}
435	}
436	
437	func headerHasBody(header string) bool {
438		if idx := index(header, "\r\n\r\n"); idx != -1 {
439			return len(trimSpace(header[idx+4:])) > 0
440		}
441		if idx := index(header, "\n\n"); idx != -1 {
442			return len(trimSpace(header[idx+2:])) > 0
443		}
444		return false
445	}
