447	//go:embed template/api.tmpl
448	var apiTemplate string
449	
450	func (ctx *apiContext) genApiCode(w io.Writer) error {
451		tmpl, err := template.
452			New("defc(api)").
453			Funcs(template.FuncMap{
454				"quote":             quote,
455				"isPointer":         isPointer,
456				"indirect":          indirect,
457				"importContext":     importContext,
458				"sub":               func(x, y int) int { return x - y },
459				"getRepr":           func(node ast.Node) string { return ctx.Doc.Repr(node) },
460				"isEllipsis":        func(node ast.Node) bool { return hasPrefix(ctx.Doc.Repr(node), "...") },
461				"methodResp":        ctx.MethodResponse,
462				"methodInner":       ctx.MethodInner,
463				"isResponse":        isResponse,
464				"isInner":           isInner,
465				"httpMethodHasBody": httpMethodHasBody,
466				"headerHasBody":     headerHasBody,
467			}).
468			Parse(apiTemplate)
469	
470		if err != nil {
471			return err
472		}
473	
474		return tmpl.Execute(w, ctx)
475	}

