 18	// JSONBody is a shortcut type used for quickly constructing an io.Reader.
 19	//
 20	// Embed JSONBody as the first field in the struct, and set the generic parameter of JSONBody
 21	// to the type of the embedded struct (ensure to use a value type rather than a pointer type).
 22	// This will allow the struct to be converted to an io.Reader and used as the body of an HTTP
 23	// request.
 24	//
 25	// Note that incorrectly setting the value of the generic type T (for example, not setting it
 26	// to a type consistent with the embedding struct) can lead to severe errors. Please adhere
 27	// to the aforementioned rule.
 28	type JSONBody[T any] struct {
 29		data bytes.Buffer
 30		once sync.Once
 31	}
 32	
 33	func (b *JSONBody[T]) Read(p []byte) (n int, err error) {
 34		b.once.Do(func() {
 35			var x T
 36			vf := reflect.ValueOf(x)
 37			if vf.Kind() != reflect.Struct {
 38				panic("use the value type of a struct rather than a pointer type as the value for generics")
 39			}
 40			vt := vf.Type()
 41			// estimate the size of the body in advance
 42			var toGrow = 0
 43			for i := 0; i < vt.NumField(); i++ {
 44				sf, sv := vt.Field(i), vf.Field(i)
 45				if i == 0 {
 46					if !sf.Anonymous || sf.Type != reflect.TypeOf(b).Elem() {
 47						panic("JSONBody is not the first embedded field of struct type T")
 48					}
 49				} else {
 50					toGrow += 8 // object keys
 51					switch sf.Type.Kind() {
 52					case reflect.String:
 53						toGrow += 2 + sv.Len()
 54					case reflect.Slice:
 55						toGrow += sv.Len() * 2
 56					default:
 57						toGrow += 4
 58					}
 59				}
 60			}
 61			b.data.Grow(toGrow)
 62			encoder := json.NewEncoder(&b.data)
 63			x = *(*T)(unsafe.Pointer(b))
 64			err = encoder.Encode(&x)
 65		})
 66		if err != nil {
 67			return 0, err
 68		}
 69		return b.data.Read(p)
 70	}
