 72	// MultipartBody is a shortcut type used for quickly constructing an io.Reader.
 73	//
 74	// Embed MultipartBody as the first field in the struct, and set the generic parameter of
 75	// MultipartBody to the type of the embedded struct (ensure to use a value type rather than a
 76	// pointer type). This will allow the struct to be converted to an io.Reader and used as the
 77	// body of an HTTP request.
 78	//
 79	// Use the ContentType method to obtain the Content-Type Header with a boundary. Use the "form"
 80	// tag to specify the name of fields in multipart/form-data, its usage is similar to the
 81	// encoding/json package, and it also supports the omitempty syntax.
 82	//
 83	// For file types, you can directly use os.File as a value, or you can use types that implement
 84	// the namedReader interface (os.File has implemented the namedReader interface).
 85	//
 86	// Note that incorrectly setting the value of the generic type T (for example, not setting it
 87	// to a type consistent with the embedding struct) can lead to severe errors. Please adhere
 88	// to the aforementioned rule.
 89	type MultipartBody[T any] struct {
 90		reader   io.Reader
 91		boundary string
 92		once     sync.Once
 93	}
 94	
 95	func (b *MultipartBody[T]) getBoundary() string {
 96		if b.boundary == "" {
 97			var buf [32]byte
 98			io.ReadFull(rand.Reader, buf[:])
 99			b.boundary = hex.EncodeToString(buf[:])
100		}
101		return b.boundary
102	}
103	
104	func (b *MultipartBody[T]) ContentType() string {
105		boundary := b.getBoundary()
106		if strings.ContainsAny(boundary, `()<>@,;:\"/[]?= `) {
107			boundary = `"` + boundary + `"`
108		}
109		return "multipart/form-data; boundary=" + boundary
110	}
111	
112	type namedReader interface {
113		io.Reader
114		Name() string
115	}
116	
117	var quoteEscaper = strings.NewReplacer("\\", "\\\\", `"`, "\\\"")
118	
119	func escapeQuotes(s string) string {
120		return quoteEscaper.Replace(s)
121	}
122	
123	func (b *MultipartBody[T]) Read(p []byte) (n int, err error) {
124		b.once.Do(func() {
125			var x T
126			x = *(*T)(unsafe.Pointer(b))
127			s := &fieldScanner{tag: "form", val: reflect.ValueOf(x)}
128			if s.val.Kind() != reflect.Struct {
129				panic("use the value type of a struct rather than a pointer type as the value for generics")
130			}
131			if !s.CheckFirstEmbedType(reflect.TypeOf(b).Elem()) {
132				panic("MultipartBody is not the first embedded field of struct type T")
133			}
134			readers := make([]io.Reader, 0, s.val.NumField())
135			for i := 0; s.Scan(); i++ {
136				tag := s.Tag()
137				if tag != "-" && s.Exported() {
138					if tagContains(tag, "omitempty") && s.Empty() {
139						continue
140					}
141					var buf bytes.Buffer
142					if i == 0 {
143						buf.WriteString("--" + b.getBoundary() + "\r\n")
144					} else {
145						buf.WriteString("\r\n--" + b.getBoundary() + "\r\n")
146					}
147					val := s.Val()
148					if file, ok := val.(namedReader); ok {
149						buf.WriteString(fmt.Sprintf(`Content-Disposition: form-data; name="%s"; filename="%s"`+"\r\n",
150							escapeQuotes(getTag(tag)),
151							escapeQuotes(file.Name())))
152						buf.WriteString("Content-Type: application/octet-stream\r\n\r\n")
153						readers = append(readers, &buf)
154						readers = append(readers, file)
155					} else {
156						var fieldvalue string
157						if fieldvalue, ok = val.(string); !ok {
158							fieldvalue = fmt.Sprintf("%v", val)
159						}
160						buf.WriteString(fmt.Sprintf(`Content-Disposition: form-data; name="%s"`+"\r\n\r\n",
161							escapeQuotes(getTag(tag))))
162						buf.WriteString(fieldvalue)
163						readers = append(readers, &buf)
164					}
165				}
166			}
167			readers = append(readers, strings.NewReader("\r\n--"+b.getBoundary()+"--\r\n"))
168			b.reader = io.MultiReader(readers...)
169		})
170		return b.reader.Read(p)
171	}
172	
173	type fieldScanner struct {
174		tag string
175		val reflect.Value
176		typ reflect.Type
177		idx int
178	}
179	
180	func (s *fieldScanner) CheckFirstEmbedType(target reflect.Type) bool {
181		if s.typ == nil {
182			s.typ = s.val.Type()
183		}
184		if s.typ.NumField() == 0 {
185			return false
186		}
187		sf := s.typ.Field(0)
188		return sf.Anonymous && sf.Type == target
189	}
190	
191	func (s *fieldScanner) pos() int {
192		return s.idx - 1
193	}
194	
195	func (s *fieldScanner) Scan() bool {
196		if s.val.Kind() != reflect.Struct {
197			return false
198		}
199		if s.typ == nil {
200			s.typ = s.val.Type()
201		}
202		s.idx++
203		if s.pos() >= s.typ.NumField() {
204			return false
205		}
206		if sf := s.typ.Field(s.pos()); sf.Anonymous {
207			s.idx++
208		}
209		return s.pos() < s.typ.NumField()
210	}
211	
212	func (s *fieldScanner) Tag() string {
213		return s.typ.Field(s.pos()).Tag.Get(s.tag)
214	}
215	
216	func (s *fieldScanner) Val() any {
217		return s.val.Field(s.pos()).Interface()
218	}
219	
220	func (s *fieldScanner) Empty() bool {
221		return s.val.Field(s.pos()).IsZero()
222	}
223	
224	func (s *fieldScanner) Exported() bool {
225		return s.typ.Field(s.pos()).IsExported()
226	}
227	
228	func getTag(tag string) string {
229		tag, _, _ = strings.Cut(tag, token.Comma)
230		return tag
231	}
232	
233	func tagContains(tag string, option string) bool {
234		parts := strings.Split(tag, token.Comma)
235		if len(parts) <= 1 {
236			return false
237		}
238		options := parts[1:]
239		for _, o := range options {
240			if strings.TrimSpace(o) == option {
241				return true
242			}
243		}
244		return false
245	}

