 87	// JSON is a Response handler that quickly adapts to interfaces with Content-Type: application/json.
 88	// You can directly use *JSON as the return type for response methods in the API Schema to handle
 89	// the JSON data returned by the interface.
 90	//
 91	// NOTE: Not suitable for pagination query interfaces. If your interface involves pagination queries,
 92	// please implement a custom Response handler.
 93	type JSON struct {
 94		Raw json.RawMessage
 95		Res *http.Response
 96	}
 97	
 98	func (j *JSON) Err() (err error) {
 99		if j.Res != nil {
100			if j.Res.StatusCode != http.StatusOK {
101				defer j.Res.Body.Close()
102				var body []byte
103				if len(j.Raw) > 0 {
104					body = j.Raw
105				} else {
106					body, err = io.ReadAll(j.Res.Body)
107					if err != nil {
108						return fmt.Errorf("error reading response body: %w", err)
109					}
110				}
111				return fmt.Errorf("response status code %d with body: \n\n%s\n\n", j.Res.StatusCode, string(body))
112			}
113		}
114		return nil
115	}
