122	func (j *JSON) FromResponse(_ string, r *http.Response) error {
123		j.Res = r
124		var (
125			ctt = r.Header.Get("Content-Type")
126			idx = -1
127		)
128		if idx = strings.IndexByte(ctt, ';'); idx < 0 {
129			idx = len(ctt)
130		}
131		defer r.Body.Close()
132		if ctt = strings.TrimSpace(ctt[:idx]); ctt == "application/json" {
133			return json.NewDecoder(r.Body).Decode(&j.Raw)
134		} else {
135			return fmt.Errorf("response content type %q is not %q", ctt, "application/json")
136		}
